using System;using System.IO;using System.Collections;using System.Linq;using UnityEngine;using UnityEditor;using Unity.XR.CoreUtils;using UnityEngine.XR;using UnityEngine.XR.Interaction.Toolkit.Inputs.Readers;using UnityEngine.XR.Interaction.Toolkit.Locomotion.Movement;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Core.Progression;using LighthouseKeepers.Gameplay.Interaction;
public class NaturalCrewDebug:MonoBehaviour{
 string folder,role;WatchDemoController w;NightmareScene scene;XROrigin rig;Transform head;ContinuousMoveProvider move;KeeperRunInput run;XRInputValueReader<Vector2> stick;HandRig hand;int failures;bool wantRun,recovering;float start;
 public static object Begin(string folder,string role){EditorUtility.audioMasterMute=true;Directory.CreateDirectory(folder);var p=new GameObject("Natural co-op nightmare probe").AddComponent<NaturalCrewDebug>();p.folder=folder;p.role=role;p.StartCoroutine(p.Go());return true;}
 void Update(){if(run)run.SampleButtons(wantRun,false,Time.unscaledDeltaTime);}
 void Log(string s){File.AppendAllText(folder+"/checks.txt",s+"\n");}void Check(bool ok,string s){Log((ok?"PASS ":"FAIL ")+s);if(!ok)failures++;}
 Vector3[] Points(string id){
  if(id=="RT-F1_F2")return new[]{new Vector3(-1.589758f,0.000000f,2.544144f),new Vector3(-1.928363f,0.000000f,2.298133f),new Vector3(-2.037470f,0.091667f,2.201980f),new Vector3(-2.141789f,0.183333f,2.100652f),new Vector3(-2.241075f,0.275000f,1.994388f),new Vector3(-2.335095f,0.366667f,1.883436f),new Vector3(-2.423627f,0.458333f,1.768059f),new Vector3(-2.506463f,0.550000f,1.648527f),new Vector3(-2.583410f,0.641667f,1.525121f),new Vector3(-2.654285f,0.733333f,1.398131f),new Vector3(-2.718923f,0.825000f,1.267855f),new Vector3(-2.777172f,0.916667f,1.134600f),new Vector3(-2.828894f,1.008333f,0.998678f),new Vector3(-2.873969f,1.100000f,0.860410f),new Vector3(-2.912289f,1.191667f,0.720119f),new Vector3(-2.943766f,1.283333f,0.578137f),new Vector3(-2.968325f,1.375000f,0.434796f),new Vector3(-2.985908f,1.466667f,0.290433f),new Vector3(-2.996475f,1.558333f,0.145387f),new Vector3(-3.000000f,1.650000f,-0.000000f),new Vector3(-2.996475f,1.741667f,-0.145387f),new Vector3(-2.985908f,1.833333f,-0.290433f),new Vector3(-2.968325f,1.925000f,-0.434796f),new Vector3(-2.943766f,2.016667f,-0.578137f),new Vector3(-2.912289f,2.108333f,-0.720119f),new Vector3(-2.873969f,2.200000f,-0.860410f),new Vector3(-2.828894f,2.291667f,-0.998678f),new Vector3(-2.777172f,2.383333f,-1.134600f),new Vector3(-2.718923f,2.475000f,-1.267855f),new Vector3(-2.654285f,2.566667f,-1.398131f),new Vector3(-2.583410f,2.658333f,-1.525121f),new Vector3(-2.506463f,2.750000f,-1.648527f),new Vector3(-2.423627f,2.841667f,-1.768059f),new Vector3(-2.335095f,2.933333f,-1.883436f),new Vector3(-2.241075f,3.025000f,-1.994388f),new Vector3(-2.141789f,3.116667f,-2.100652f),new Vector3(-2.037470f,3.208333f,-2.201980f),new Vector3(-1.928363f,3.300000f,-2.298133f),new Vector3(-1.589758f,3.300000f,-2.544144f)};
  if(id=="RT-F1-ENTRY")return new[]{new Vector3(0.000000f,0.000000f,-3.850000f),new Vector3(0.000000f,0.000000f,-1.700000f),new Vector3(-1.200000f,0.000000f,-0.700000f),new Vector3(-1.200000f,0.000000f,1.000000f),new Vector3(-0.300000f,0.000000f,1.700000f),new Vector3(-1.026060f,0.000000f,2.819078f),new Vector3(-1.589758f,0.000000f,2.544144f)};
  throw new ArgumentException(id);
 }
 IEnumerator Walk(Vector3 goal,string label,float tolerance=.2f){float until=Time.time+7;while(Time.time<until&&!w.State.Failed&&!w.State.Recovery.Downed((int)w.CurrentDuty)){var d=Vector3.ProjectOnPlane(goal-rig.transform.position,Vector3.up);if(d.magnitude<tolerance)break;var f=Vector3.ProjectOnPlane(head.forward,Vector3.up).normalized;var r=Vector3.Cross(Vector3.up,f);d.Normalize();stick.manualValue=new Vector2(Vector3.Dot(d,r),Vector3.Dot(d,f));if(run.Remaining<=.01f)recovering=true;else if(run.Remaining>=.95f)recovering=false;wantRun=!recovering;yield return null;}float dist=Vector3.ProjectOnPlane(goal-rig.transform.position,Vector3.up).magnitude;if(dist>=tolerance)Check(false,label+" stuck/caught at "+rig.transform.position+" goal "+goal+" beat "+w.State.Scare.Beat);}
 IEnumerator Door(int index){stick.manualValue=Vector2.zero;wantRun=false;if(role=="lead"){var target=scene.DoorTarget(index*2);var d=hand.Direct;hand.transform.parent.gameObject.SetActive(true);hand.enabled=false;d.enabled=true;d.selectInput=new XRInputButtonReader("crew physical grip",inputSourceMode:XRInputButtonReader.InputSourceMode.ManualValue);d.selectInput.QueueManualState(false,0);hand.transform.parent.position=target.transform.position;Physics.SyncTransforms();yield return new WaitForSeconds(.15f);d.selectInput.QueueManualState(true,1);yield return new WaitForSeconds(.2f);Check(d.hasSelection,"Door "+index+" actual direct grip");for(int i=0;i<12&&w.State.Scare.Door(index)<.75f;i++){hand.transform.parent.position+=Vector3.back*.08f;Physics.SyncTransforms();yield return new WaitForSeconds(.1f);}Check(w.State.Scare.Door(index)>=.72f,"Door "+index+" opened by grip and pull");d.selectInput.QueueManualState(false,0);}else{float limit=Time.time+8;while(Time.time<limit&&w.State.Scare.Door(index)<.72f&&!w.State.Failed&&!w.State.Recovery.Downed((int)w.CurrentDuty))yield return null;Check(w.State.Scare.Door(index)>=.72f,"Partner opens shared door "+index);}}

 IEnumerator Navigate(Vector3 goal,string label){using(var nav=new HunterNavigation(HorrorTuning.Current,Resources.Load<UnityEngine.AI.NavMeshData>("HunterNavigation"))){var feet=new Vector3(head.position.x,rig.transform.position.y,head.position.z);if(!nav.Route(feet,goal,out var path)){Check(false,label+" has no NavMesh route from "+feet);yield break;}for(int i=1;i<path.Length;i++){yield return Walk(path[i],label,.22f);if(failures>0||w.State.Failed)yield break;}}}
 IEnumerator Go(){w=FindAnyObjectByType<WatchDemoController>();scene=w.GetComponent<NightmareScene>();rig=FindAnyObjectByType<XROrigin>();head=rig.Camera.transform;foreach(var b in rig.GetComponentsInChildren<Behaviour>(true))if(b.GetType().Name.Contains("TrackedPose")||b.GetType().Name.Contains("InputModality")||b.GetType().Name=="DesktopPreview")b.enabled=false;move=rig.GetComponentInChildren<ContinuousMoveProvider>();stick=new XRInputValueReader<Vector2>("natural crew escape stick",XRInputValueReader.InputSourceMode.ManualValue);move.leftHandMoveInput=stick;hand=rig.GetComponentsInChildren<HandRig>(true).First(h=>h.Node==XRNode.RightHand);run=w.GetComponent<KeeperRunInput>();run.enabled=false;File.WriteAllText(folder+"/ready.txt",w.CurrentDuty.ToString());start=Time.time;float limit=Time.time+115;ScareBeat last=ScareBeat.Idle;
 using(var nav=new HunterNavigation(HorrorTuning.Current,Resources.Load<UnityEngine.AI.NavMeshData>("HunterNavigation"))){Vector3[] route=null;float nextPath=0;while(Time.time<limit&&w.State.Scare.Beat<ScareBeat.Turn&&!w.State.Failed){var c=w.State.Scare;if(c.Beat!=last){last=c.Beat;Log("Observed "+last+" at "+(Time.time-start).ToString("F1")+" pos "+rig.transform.position+" child "+c.Body);}head.LookAt(c.Body+Vector3.up*1.1f);wantRun=false;stick.manualValue=Vector2.zero;
  var feet=new Vector3(head.position.x,rig.transform.position.y,head.position.z);float gap=Vector3.Distance(feet,c.Body);
  if((c.Beat==ScareBeat.Follow||c.Beat==ScareBeat.Corner)&&gap>1.8f){if(Time.unscaledTime>=nextPath){nextPath=Time.unscaledTime+.35f;if(!nav.Route(feet,c.Body,out route))route=null;}if(route!=null&&route.Length>1){int j=1;while(j<route.Length-1&&Vector3.ProjectOnPlane(route[j]-feet,Vector3.up).magnitude<.24f)j++;var d=Vector3.ProjectOnPlane(route[j]-feet,Vector3.up);if(d.sqrMagnitude>.0001f){d.Normalize();var f=Vector3.ProjectOnPlane(head.forward,Vector3.up).normalized;stick.manualValue=new Vector2(Vector3.Dot(d,Vector3.Cross(Vector3.up,f)),Vector3.Dot(d,f));}}}
  yield return null;}}
 stick.manualValue=Vector2.zero;Check(w.State.Scare.Beat==ScareBeat.Turn,"Both players naturally gaze and follow child to F2");while(Time.time<limit&&w.State.Scare.Beat!=ScareBeat.Escape&&!w.State.Failed){head.LookAt(GameObject.Find("Nightmare child").transform.position+Vector3.up*.4f);if(w.State.Scare.Beat!=last){last=w.State.Scare.Beat;w.DrownedViewers(out var a,out var p,out var f,out var b,out var q,out var g);Log("Beat "+last+" a="+a+" p="+p.ToString("F3")+" f="+f.ToString("F3")+" b="+b+" q="+q.ToString("F3")+" g="+g.ToString("F3")+" child="+w.State.Scare.Body.ToString("F3"));}yield return null;}Check(w.State.Scare.Beat==ScareBeat.Escape,"Turn, warning and quiet lead naturally to escape");Log("Chase starts at "+rig.transform.position+" child "+w.State.Scare.Body+" lead "+HorrorTuning.Current.nightmareChaseLeadSeconds);start=Time.time;
 if(failures==0)yield return Navigate(new Vector3(-1.22f,3.3f,-2.74f),"Reach stair landing");var stairs=Points("RT-F1_F2");Array.Reverse(stairs);foreach(var pnt in stairs){if(failures>0||w.State.Failed)break;yield return Walk(pnt,"Stair route");}Check(failures==0&&rig.transform.position.y<.35f,"Descend to F1 with XRI locomotion");
 if(failures==0){var entry=Points("RT-F1-ENTRY");Array.Reverse(entry);foreach(var pnt in entry){if(pnt.z< -3.4f||failures>0)break;yield return Walk(pnt,"F1 route");}}
 if(failures==0){yield return Walk(new Vector3(0,0,-3.25f),"Door approach");yield return Door(0);}if(failures==0){yield return Walk(new Vector3(0,0,-4.5f),"First threshold");yield return Walk(new Vector3(0,0,-6.5f),"House aisle");yield return Walk(new Vector3(0,0,-9.25f),"Exit approach");yield return Door(1);}if(failures==0){yield return Walk(new Vector3(0,0,-10.6f),"Exterior");stick.manualValue=Vector2.zero;wantRun=false;float deadline=Time.time+10;while(Time.time<deadline&&w.State.Scare.Beat==ScareBeat.Escape&&!w.State.Failed)yield return null;Check(w.State.Scare.Beat==ScareBeat.Return,"Both escaped into the storm");}
 if(failures==0){yield return Walk(new Vector3(0,0,-9.1f),"Return through outer door");stick.manualValue=Vector2.zero;wantRun=false;float deadline=Time.time+10;while(Time.time<deadline&&w.State.Scare.Beat==ScareBeat.Return&&!w.State.Failed)yield return null;Check(w.State.Scare.Beat==ScareBeat.Relief,"Both returned inside and relief began");}
 stick.manualValue=Vector2.zero;wantRun=false;Log("Escape elapsed="+(Time.time-start).ToString("F2")+" beat="+w.State.Scare.Beat+" pos="+rig.transform.position+" body="+w.State.Scare.Body+" caught="+w.State.Scare.Caught);File.WriteAllText(folder+"/result.json","{\"passed\":"+(failures==0?"true":"false")+",\"failures\":"+failures+"}");Destroy(gameObject);}
}
